import yaml from "yaml";

/**
 * Where a generated block starts and ends.
 *
 * A comment rather than a fence, because the file has to stay readable on
 * GitHub and in an editor: the markers disappear when it is rendered, and the
 * generated table between them reads like the prose around it.
 */
const OPEN = /^<!-- amy:generated ([a-z0-9-]+) -->$/;
const CLOSE = /^<!-- amy:end ([a-z0-9-]+) -->$/;

/** The banner a wholly generated file carries, so nobody edits one by hand. */
export function banner(source) {
  return `<!-- Generated by \`npm run docs:generate\` from ${source}. Do not edit by hand. -->`;
}

export function frontmatter(text) {
  if (!text.startsWith("---\n")) return { data: {}, body: text };

  const end = text.indexOf("\n---", 4);
  if (end === -1) return { data: {}, body: text };

  const data = yaml.parse(text.slice(4, end)) ?? {};
  const body = text.slice(end + 4).replace(/^\n/, "");
  return { data, body };
}

/** The `##`-and-deeper headings of a page, for a site's on-page navigation. */
export function headings(body) {
  const found = [];

  for (const line of body.split("\n")) {
    const match = /^(#{2,4}) (.+)$/.exec(line);
    if (!match) continue;

    const title = match[2].replace(/`/g, "").trim();
    found.push({ depth: match[1].length, title, slug: slug(title) });
  }

  return found;
}

function slug(title) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .trim()
    .replace(/\s+/g, "-");
}

/** Which generated blocks a page declares, in the order they appear. */
export function blocksIn(text) {
  const names = [];

  for (const line of text.split("\n")) {
    const match = OPEN.exec(line.trim());
    if (match) names.push(match[1]);
  }

  return names;
}

/**
 * Puts each generated block's current content into the page.
 *
 * Everything outside the markers is left exactly as it was: the prose is the
 * author's and the table is the generator's, and neither writes over the
 * other. A page naming a block the generator does not produce is an error
 * rather than an empty section, because a reference that quietly renders
 * nothing is worse than one that will not build.
 */
export function splice(text, blocks, describe) {
  const lines = text.split("\n");
  const out = [];
  const problems = [];

  let skippingUntil = null;

  for (const line of lines) {
    if (skippingUntil) {
      const close = CLOSE.exec(line.trim());
      if (close && close[1] === skippingUntil) {
        out.push(line);
        skippingUntil = null;
      } else if (close) {
        problems.push(
          `${describe}: block \`${skippingUntil}\` is closed by \`${close[1]}\``,
        );
        out.push(line);
        skippingUntil = null;
      }
      continue;
    }

    out.push(line);

    const open = OPEN.exec(line.trim());
    if (!open) continue;

    const name = open[1];
    const content = blocks[name];
    if (content === undefined) {
      problems.push(
        `${describe}: names the generated block \`${name}\`, which nothing produces`,
      );
      skippingUntil = name;
      continue;
    }

    out.push("", content.trimEnd(), "");
    skippingUntil = name;
  }

  if (skippingUntil) {
    problems.push(`${describe}: block \`${skippingUntil}\` is never closed`);
  }

  return { text: out.join("\n"), problems };
}

/** A markdown table, with every cell escaped so a pipe in prose survives. */
export function table(headers, rows) {
  if (rows.length === 0) return "_Nothing._";

  const escape = (cell) => String(cell ?? "").replace(/\|/g, "\\|").replace(/\n+/g, " ").trim();

  return [
    `| ${headers.join(" | ")} |`,
    `| ${headers.map(() => ":--").join(" | ")} |`,
    ...rows.map((row) => `| ${row.map(escape).join(" | ")} |`),
  ].join("\n");
}

/** A value as it would be written in YAML, for a defaults column. */
export function literal(value) {
  if (value === undefined) return "";
  if (typeof value === "string") return value === "" ? '`""`' : `\`${value}\``;
  if (Array.isArray(value)) return value.length === 0 ? "`[]`" : `\`${JSON.stringify(value)}\``;
  if (value !== null && typeof value === "object") {
    return Object.keys(value).length === 0 ? "`{}`" : `\`${JSON.stringify(value)}\``;
  }
  return `\`${JSON.stringify(value)}\``;
}
